export const SIMULATE_SCRIPTS: Record<string, string> = {
  "generate.py": "\"\"\"Generate the blind synthetic cohort + the test personas (MIN-4505). Seeded: same seed, same files.\nSynthetic only. Not tuned to any real person. No names, no real ids, country only.\nUsage: python3 generate.py <out_dir> [--n 400] [--sarcoid S]\n--n       cohort size (default 400; the default output is byte-identical to the committed data/synthetic files).\n          Common patterns scale with n/400; the rare patterns keep their size (fewer than 5, never shown).\n--sarcoid size of the rare_sarcoid_like pattern (the demo patient's pattern). Default 3. Used for the 5,000 run (MIN-4504).\n\"\"\"\nimport json, random, sys, os\nfrom match import LAB_DEFS, IMAGING, SYMPTOMS, SPECIALTIES, features\n\nSEED = 20261114\nN = 400\nCOUNTRIES = [(\"GR\", 5), (\"DE\", 4), (\"FR\", 3), (\"ES\", 3), (\"IT\", 3), (\"NL\", 2), (\"PT\", 2), (\"SE\", 1), (\"CY\", 1)]\nAGE_BANDS = [\"18-29\", \"30-39\", \"40-49\", \"50-59\", \"60-69\", \"70+\"]\n# lab code -> (marker, direction)\nCODE_TO_LAB = {}\nfor m, (_u, _lo, _hi, a, b) in LAB_DEFS.items():\n    if a: CODE_TO_LAB[a] = (m, \"above\")\n    if b: CODE_TO_LAB[b] = (m, \"below\")\n\n# name: size, core codes with presence probability, age bands, sex weights (F share), \nCLUSTERS = [\n    (\"inflammatory_back_pain\", 28, {\"CRP_high\": .9, \"ESR_high\": .85, \"HLA_B27_positive\": .95, \"morning_stiffness\": .9,\n        \"low_back_pain\": .95, \"img_sacroiliitis\": .85, \"spec_orthopaedics\": .8, \"spec_rheumatology\": .85}, [0, 1, 2], .35),\n    (\"rheumatoid_arthritis\", 26, {\"RF_positive\": .9, \"anti_CCP_positive\": .9, \"CRP_high\": .85, \"joint_pain\": .95,\n        \"morning_stiffness\": .85, \"hand_swelling\": .7, \"spec_rheumatology\": .9}, [2, 3, 4], .75),\n    (\"hypothyroid\", 26, {\"TSH_high\": .95, \"fatigue\": .9, \"cold_intolerance\": .8, \"weight_gain\": .75, \"spec_endocrinology\": .75,\n        \"spec_gp\": .6}, [1, 2, 3, 4], .85),\n    (\"type2_diabetes_metabolic\", 30, {\"HbA1c_high\": .95, \"LDL_high\": .8, \"polyuria\": .75, \"fatigue\": .7,\n        \"spec_endocrinology\": .8, \"spec_cardiology\": .4}, [3, 4, 5], .45),\n    (\"iron_deficiency\", 22, {\"Hb_low\": .95, \"ferritin_low\": .95, \"fatigue\": .9, \"headache\": .6, \"spec_gp\": .8,\n        \"spec_gastroenterology\": .55}, [0, 1, 2], .9),\n    (\"lupus_like\", 14, {\"ANA_positive\": .95, \"joint_pain\": .85, \"rash\": .8, \"fatigue\": .8, \"WBC_low\": .65,\n        \"spec_rheumatology\": .9}, [0, 1, 2], .9),\n    (\"gout\", 12, {\"uric_acid_high\": .95, \"joint_pain\": .9, \"CRP_high\": .6, \"spec_orthopaedics\": .6,\n        \"spec_rheumatology\": .5}, [3, 4, 5], .15),\n    (\"hyperthyroid\", 12, {\"TSH_low\": .95, \"palpitations\": .85, \"heat_intolerance\": .8, \"weight_loss\": .8, \"tremor\": .6,\n        \"spec_endocrinology\": .8, \"spec_cardiology\": .5}, [1, 2, 3], .8),\n    (\"reduced_kidney_function\", 10, {\"creatinine_high\": .95, \"leg_oedema\": .7, \"fatigue\": .7, \"spec_nephrology\": .9,\n        \"spec_cardiology\": .5}, [4, 5], .45),\n    (\"low_bone_density\", 15, {\"vitD_low\": .9, \"img_osteopenia\": .9, \"bone_pain\": .8, \"spec_orthopaedics\": .8,\n        \"spec_endocrinology\": .4}, [4, 5], .85),\n    # rare patterns: fewer than 5 members each, they must never come back from the matching\n    (\"rare_sarcoid_like\", 3, {\"ACE_high\": .98, \"img_hilar_lymphadenopathy\": .98, \"cough\": .95, \"dry_eyes\": .9,\n        \"spec_pulmonology\": .95}, [2, 3], .5),\n    (\"rare_copper_metabolism\", 2, {\"ceruloplasmin_low\": .98, \"ALT_high\": .98, \"tremor\": .95, \"spec_hepatology\": .95,\n        \"spec_neurology\": .95}, [0, 1], .5),\n    (\"rare_myopathy\", 4, {\"CK_high\": .98, \"muscle_weakness\": .98, \"ALT_high\": .9, \"spec_neurology\": .9,\n        \"spec_rheumatology\": .8}, [1, 2, 3], .5),\n]\nNOISE_CODES = ([\"CRP_high\", \"vitD_low\", \"ferritin_low\", \"LDL_high\", \"ALT_high\", \"ESR_high\", \"WBC_high\", \"TSH_high\"] * 2\n               + [\"headache\", \"fatigue\", \"joint_pain\", \"low_back_pain\", \"cough\", \"rash\", \"weight_gain\", \"polyuria\"] * 2\n               + [\"img_disc_degeneration\", \"img_joint_effusion\", \"spec_gp\", \"spec_cardiology\", \"spec_orthopaedics\"] * 2)\n\n\ndef month(rng, lo=1, hi=36):\n    \"\"\"A month/year date, 1..36 months before Nov 2026. Never a day.\"\"\"\n    back = rng.randint(lo, hi)\n    y, m = divmod(2026 * 12 + 10 - back, 12)\n    return \"%04d-%02d\" % (y, m + 1)\n\n\ndef lab_value(rng, marker, state):\n    unit, lo, hi, _a, _b = LAB_DEFS[marker]\n    if unit == \"qual\":\n        return 1 if state == \"above\" else 0\n    span = (hi - lo) or 1.0\n    if state == \"above\":\n        v = hi + span * rng.uniform(0.15, 1.2)\n    elif state == \"below\":\n        v = lo - span * rng.uniform(0.1, 0.5)\n        v = max(v, lo * 0.2)\n    else:\n        v = rng.uniform(lo + 0.15 * span, hi - 0.15 * span)\n    return round(v, 1 if hi < 100 else 0)\n\n\ndef build(rng, pid, intended, country, age, sex, opt_in):\n    labs, imaging, symptoms, specs = [], [], [], []\n    states = {}\n    for code in sorted(intended):   # sets iterate in hash order: sort, or the seed means nothing\n        if code in CODE_TO_LAB:\n            m, st = CODE_TO_LAB[code]\n            states[m] = st\n        elif code in IMAGING:\n            imaging.append({\"code\": code, \"date\": month(rng)})\n        elif code in SYMPTOMS:\n            symptoms.append(code)\n        elif code in SPECIALTIES:\n            specs.append(code)\n    # a normal panel for some other markers, so records look like real folders\n    others = [m for m in LAB_DEFS if m not in states]\n    for m in rng.sample(others, rng.randint(3, 6)):\n        states[m] = \"normal\"\n    for m, st in states.items():\n        unit, lo, hi, _a, _b = LAB_DEFS[m]\n        latest = month(rng, 1, 18)\n        labs.append({\"marker\": m, \"value\": lab_value(rng, m, st), \"unit\": unit, \"ref_low\": lo, \"ref_high\": hi, \"date\": latest})\n        if rng.random() < 0.3:   # an older, different result: the latest one decides\n            older = month(rng, 19, 36)\n            old_state = \"normal\" if st != \"normal\" else rng.choice([\"normal\", \"above\" if LAB_DEFS[m][3] else \"normal\"])\n            if unit != \"qual\" or old_state == \"normal\":\n                labs.append({\"marker\": m, \"value\": lab_value(rng, m, old_state), \"unit\": unit, \"ref_low\": lo,\n                             \"ref_high\": hi, \"date\": older})\n    if not specs:\n        specs = [\"spec_gp\"] if rng.random() < .6 else []\n    return {\"id\": pid, \"synthetic\": True, \"label\": \"seeded, synthetic\", \"country\": country, \"age_band\": age,\n            \"sex\": sex, \"matching_opt_in\": opt_in, \"labs\": labs, \"imaging\": imaging,\n            \"symptoms\": sorted(symptoms), \"specialties\": sorted(set(specs))}\n\n\ndef make_cohort(rng, n=N, sarcoid=None):\n    cw = [c for c, w in COUNTRIES for _ in range(w)]\n    people, tags = [], []\n    for name, size, core, ages, f_share in CLUSTERS:\n        if name == \"rare_sarcoid_like\" and sarcoid is not None:\n            size = sarcoid\n        elif n != N and not name.startswith(\"rare_\"):\n            size = round(size * n / N)\n        for _ in range(size):\n            intended = {c for c, p in core.items() if rng.random() < p}\n            for c in rng.sample(NOISE_CODES, rng.choice([0, 0, 1, 2])):   # incidental extras\n                intended.add(c)\n            people.append((intended, rng.choice(ages), \"F\" if rng.random() < f_share else \"M\"))\n            tags.append(name)\n    while len(people) < n:   # noise patients: scattered, no shared pattern\n        intended = set(rng.sample(NOISE_CODES, rng.randint(1, 4)))\n        people.append((intended, rng.randrange(6), \"F\" if rng.random() < .5 else \"M\"))\n        tags.append(\"noise\")\n    order = list(range(len(people)))\n    rng.shuffle(order)   # ids carry no cluster information\n    cohort, truth = [], {}\n    for n, i in enumerate(order, 1):\n        intended, age, sex = people[i]\n        pid = \"syn-%04d\" % n\n        rec = build(rng, pid, intended, rng.choice(cw), AGE_BANDS[age], sex, rng.random() < 0.9)\n        cohort.append(rec)\n        truth[pid] = tags[i]\n    return cohort, truth\n\n\ndef make_persona(rng, pid, intended, opt_in, country=\"GR\", age=\"50-59\", sex=\"F\"):\n    return build(rng, pid, set(intended), country, age, sex, opt_in)\n\n\ndef make_personas():\n    prng = random.Random(SEED + 1)\n    maria_codes = [\"CRP_high\", \"RF_positive\", \"anti_CCP_positive\", \"joint_pain\", \"morning_stiffness\", \"spec_rheumatology\"]\n    return {\n        \"maria\": make_persona(prng, \"persona-maria\", maria_codes, True),\n        \"maria_not_opted_in\": make_persona(prng, \"persona-maria-no-optin\", maria_codes, False),\n        \"rare\": make_persona(prng, \"persona-rare\", [\"ACE_high\", \"img_hilar_lymphadenopathy\", \"cough\", \"dry_eyes\", \"spec_pulmonology\"], True, \"DE\", \"40-49\", \"M\"),\n        \"no_pattern\": make_persona(prng, \"persona-no-pattern\", [\"spec_gp\"], True, \"FR\", \"30-39\", \"F\"),\n    }\n\n\ndef main(out, n=N, sarcoid=None):\n    os.makedirs(out, exist_ok=True)\n    rng = random.Random(SEED)\n    cohort, truth = make_cohort(rng, n, sarcoid)\n    personas = make_personas()\n    dump = lambda name, obj: open(os.path.join(out, name), \"w\").write(json.dumps(obj, indent=1, sort_keys=True) + \"\\n\")\n    dump(\"cohort.json\", {\"synthetic\": True, \"label\": \"seeded, synthetic\", \"seed\": SEED, \"records\": cohort})\n    dump(\"persona-maria.json\", personas[\"maria\"])\n    dump(\"test-personas.json\", personas)\n    # truth: which cluster generated whom. Test/debug only, never part of the cohort the matching sees.\n    sizes = {}\n    for t in truth.values(): sizes[t] = sizes.get(t, 0) + 1\n    dump(\"cohort-seed-summary.json\", {\"seed\": SEED, \"cohort_size\": len(cohort), \"opted_in\": sum(r[\"matching_opt_in\"] for r in cohort),\n                                      \"seeded_patterns\": sizes})\n    if n != N:   # which seeded pattern made each row: for the dot colours of the demo page only, never read by the matching\n        dump(\"cohort-truth.json\", {\"seed\": SEED, \"n\": n, \"sarcoid\": sarcoid, \"truth\": truth})\n    print(\"cohort\", len(cohort), \"opted_in\", sum(r[\"matching_opt_in\"] for r in cohort))\n    print(\"seeded patterns\", json.dumps(sizes, sort_keys=True))\n\n\nif __name__ == \"__main__\":\n    import argparse\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\"out\", nargs=\"?\", default=\"out\")\n    ap.add_argument(\"--n\", type=int, default=N)\n    ap.add_argument(\"--sarcoid\", type=int, default=None)\n    a = ap.parse_args()\n    main(a.out, a.n, a.sarcoid)\n",
  "match.py": "\"\"\"Matching logic for the seeded synthetic cohort (MIN-4505, offline part).\n\nMirrors the future Supabase RPC. Kept as plain set operations so it ports to one SQL function:\n  features(patient)  -> rows (patient_id, code)   [a view / CTE over the exam rows]\n  shared             -> persona codes ∩ record codes (join on code)\n  group              -> GROUP BY array_agg(code ORDER BY code) HAVING count(*) >= K\n  opt-in             -> WHERE matching_opt_in (persona and cohort rows), checked in the same query\nSynthetic data only. No names, no exact dates and nothing below country leave this function.\n\"\"\"\nfrom collections import defaultdict\n\nK = 5                 # k-anonymity: a pattern shared by fewer than K cohort rows == \"no matches\"\nMIN_SHARED = 4        # a record matches when it shares at least this many of the persona's codes\nLABEL = \"seeded, synthetic\"\nEMPTY = {\"match_count\": 0, \"groups\": []}   # the ONE empty answer: no opt-in, no match, count < K\n\n# marker -> (unit, ref_low, ref_high, code_if_above, code_if_below). Qualitative markers: 0 = negative, 1 = positive.\nLAB_DEFS = {\n    \"CRP\":        (\"mg/L\", 0, 5, \"CRP_high\", None),\n    \"ESR\":        (\"mm/h\", 0, 20, \"ESR_high\", None),\n    \"RF\":         (\"IU/mL\", 0, 14, \"RF_positive\", None),\n    \"anti_CCP\":   (\"U/mL\", 0, 20, \"anti_CCP_positive\", None),\n    \"ANA\":        (\"qual\", 0, 0, \"ANA_positive\", None),\n    \"HLA_B27\":    (\"qual\", 0, 0, \"HLA_B27_positive\", None),\n    \"TSH\":        (\"mIU/L\", 0.4, 4.0, \"TSH_high\", \"TSH_low\"),\n    \"HbA1c\":      (\"%\", 4.0, 5.6, \"HbA1c_high\", None),\n    \"LDL\":        (\"mg/dL\", 0, 130, \"LDL_high\", None),\n    \"Ferritin\":   (\"ng/mL\", 30, 300, None, \"ferritin_low\"),\n    \"Hemoglobin\": (\"g/dL\", 12.0, 17.5, None, \"Hb_low\"),\n    \"WBC\":        (\"10^9/L\", 4.0, 11.0, \"WBC_high\", \"WBC_low\"),\n    \"VitD\":       (\"ng/mL\", 30, 100, None, \"vitD_low\"),\n    \"Creatinine\": (\"mg/dL\", 0.6, 1.3, \"creatinine_high\", None),\n    \"UricAcid\":   (\"mg/dL\", 3.5, 7.2, \"uric_acid_high\", None),\n    \"ALT\":        (\"U/L\", 7, 40, \"ALT_high\", None),\n    \"ACE\":        (\"U/L\", 8, 52, \"ACE_high\", None),\n    \"Ceruloplasmin\": (\"mg/dL\", 20, 60, None, \"ceruloplasmin_low\"),\n    \"CK\":         (\"U/L\", 30, 200, \"CK_high\", None),\n}\nIMAGING = [\"img_sacroiliitis\", \"img_disc_degeneration\", \"img_joint_effusion\", \"img_osteopenia\",\n           \"img_hand_erosions\", \"img_hilar_lymphadenopathy\", \"img_normal\"]\nSYMPTOMS = [\"morning_stiffness\", \"low_back_pain\", \"joint_pain\", \"fatigue\", \"weight_loss\", \"weight_gain\",\n            \"polyuria\", \"palpitations\", \"cold_intolerance\", \"heat_intolerance\", \"rash\", \"headache\",\n            \"cough\", \"dry_eyes\", \"hand_swelling\", \"bone_pain\", \"muscle_weakness\", \"tremor\", \"leg_oedema\"]\nSPECIALTIES = [\"spec_orthopaedics\", \"spec_rheumatology\", \"spec_gp\", \"spec_endocrinology\", \"spec_cardiology\",\n               \"spec_gastroenterology\", \"spec_nephrology\", \"spec_pulmonology\", \"spec_neurology\", \"spec_hepatology\"]\nIGNORED = {\"img_normal\"}   # carries no pattern information\n# LOINC step 1 (MIN-4689): LOINC code -> marker, for the codes of supabase/sql/020_lab_loinc.sql whose analyte_key is a\n# LAB_DEFS marker (seed_sql.ANALYTE_KEY). A lab row that carries one of these codes (\"loinc\") is that marker, whatever\n# its \"marker\" says; a row without a code, or with a code that is not here, keeps its \"marker\". The synthetic records\n# carry no code, so every output of this file is unchanged. test_match_loinc.py fails when this map and 020 disagree.\nLOINC = {\n    \"2742-5\": \"ACE\", \"1742-6\": \"ALT\", \"33253-6\": \"ANA\", \"5048-4\": \"ANA\", \"8061-4\": \"ANA\", \"2157-6\": \"CK\",\n    \"1988-5\": \"CRP\", \"30522-7\": \"CRP\", \"2064-4\": \"Ceruloplasmin\", \"2160-0\": \"Creatinine\", \"30341-2\": \"ESR\",\n    \"4537-7\": \"ESR\", \"2276-4\": \"Ferritin\", \"26043-0\": \"HLA_B27\", \"4821-5\": \"HLA_B27\", \"17856-6\": \"HbA1c\",\n    \"4548-4\": \"HbA1c\", \"59261-8\": \"HbA1c\", \"718-7\": \"Hemoglobin\", \"13457-7\": \"LDL\", \"18262-6\": \"LDL\",\n    \"2089-1\": \"LDL\", \"11572-5\": \"RF\", \"11580-8\": \"TSH\", \"3016-3\": \"TSH\", \"3084-1\": \"UricAcid\", \"1989-3\": \"VitD\",\n    \"62292-8\": \"VitD\", \"26464-8\": \"WBC\", \"6690-2\": \"WBC\", \"33935-8\": \"anti_CCP\", \"53027-9\": \"anti_CCP\",\n}\n\n\ndef latest_labs(patient):\n    \"\"\"Latest result per marker (month/year strings sort correctly). The marker is the row's LOINC code's, if it has one.\"\"\"\n    best = {}\n    for lab in patient[\"labs\"]:\n        marker = LOINC.get(lab.get(\"loinc\"), lab[\"marker\"])\n        if marker not in best or lab[\"date\"] > best[marker][\"date\"]:\n            best[marker] = lab\n    return best\n\n\ndef features(patient):\n    \"\"\"Derive the coded features of one patient from raw results. Demographics are never features.\"\"\"\n    out = set()\n    for marker, lab in latest_labs(patient).items():\n        _, lo, hi, above, below = LAB_DEFS[marker]\n        if above and lab[\"value\"] > hi:\n            out.add(above)\n        if below and lab[\"value\"] < lo:\n            out.add(below)\n    out.update(f[\"code\"] for f in patient[\"imaging\"])\n    out.update(patient[\"symptoms\"])\n    out.update(patient[\"specialties\"])\n    return frozenset(out - IGNORED)\n\n\ndef find_matches(persona, cohort, k=K, min_shared=MIN_SHARED, feats=None):\n    \"\"\"Returns EMPTY or {\"match_count\": n, \"groups\": [{n, pattern, countries, label}]}.\n    Only the pattern, the count and countries leave this function.\n    feats: optional {id: features} cache (speed only, same result).\"\"\"\n    feats = feats if feats is not None else {}\n    if not persona.get(\"matching_opt_in\"):\n        return dict(EMPTY, groups=[])\n    pf = features(persona)\n    groups = defaultdict(list)\n    for rec in cohort:\n        if not rec.get(\"matching_opt_in\") or rec[\"id\"] == persona[\"id\"]:\n            continue\n        if rec[\"id\"] not in feats:\n            feats[rec[\"id\"]] = features(rec)\n        shared = pf & feats[rec[\"id\"]]\n        if len(shared) >= min_shared:\n            groups[shared].append(rec[\"country\"])\n    out = [{\"n\": len(c), \"pattern\": sorted(p), \"countries\": sorted(set(c)), \"label\": LABEL}\n           for p, c in groups.items() if len(c) >= k]\n    if not out:\n        return dict(EMPTY, groups=[])\n    out.sort(key=lambda g: (-g[\"n\"], g[\"pattern\"]))\n    return {\"match_count\": sum(g[\"n\"] for g in out), \"groups\": out}\n",
  "build_run.py": "\"\"\"Build the browser-ready file of the doctor-simulate page (MIN-4504). Synthetic only.\n\n  python3 build_run.py <cohort_dir> <out.json>     cohort_dir = output of: generate.py <dir> --n 5000 --sarcoid S\n  python3 build_run.py --sweep                     find S: start at 6, +1 until the demo patient gets exactly one group of 5 to 9\n\nThe file holds the 5,000 records as coded features (no names, country and age band only), the demo patient\n(persona-rare), the result of the real matcher (match.py), and the dummy exams of the matched records only.\nThe page re-runs the matching in the browser; the \"result\" block is what its test must equal.\n\"\"\"\nimport json, os, random, sys\nfrom collections import defaultdict\nimport generate as G\nfrom match import find_matches, features, K, MIN_SHARED\n\nPAGE_LABEL = \"Seeded synthetic data. Not real patients.\"\n\n\ndef sweep():\n    persona = G.make_personas()[\"rare\"]\n    s = 6\n    while True:\n        cohort, _ = G.make_cohort(random.Random(G.SEED), 5000, s)\n        r = find_matches(persona, cohort)\n        sizes = [g[\"n\"] for g in r[\"groups\"]]\n        k1 = find_matches(persona, cohort, k=1)\n        print(\"S=%d  groups shown=%s  match_count=%d  (k=1 control, exact-set groups of: %s)\" % (\n            s, sizes, r[\"match_count\"], sorted((g[\"n\"] for g in k1[\"groups\"]), reverse=True)))\n        if len(sizes) == 1 and 5 <= sizes[0] <= 9:\n            print(\"-> S = %d\" % s)\n            return s\n        s += 1\n\n\ndef build(cohort_dir, out):\n    rd = lambda f: json.load(open(os.path.join(cohort_dir, f)))\n    cohort = rd(\"cohort.json\")[\"records\"]\n    persona = rd(\"test-personas.json\")[\"rare\"]\n    truth = rd(\"cohort-truth.json\")\n    summary = rd(\"cohort-seed-summary.json\")\n    assert persona[\"id\"] == \"persona-rare\" and len(cohort) == truth[\"n\"] == 5000\n    feats = {r[\"id\"]: features(r) for r in cohort}\n    pf = features(persona)\n    codes = sorted(set().union(*feats.values()) | pf)\n    cx = {c: i for i, c in enumerate(codes)}\n    names = sorted(set(truth[\"truth\"].values()))\n    gx = {g: i for i, g in enumerate(names)}\n    rows = [[r[\"country\"], G.AGE_BANDS.index(r[\"age_band\"]), 1 if r[\"matching_opt_in\"] else 0, gx[truth[\"truth\"][r[\"id\"]]],\n             sorted(cx[c] for c in feats[r[\"id\"]])] for r in cohort]\n\n    res = find_matches(persona, cohort, feats=feats)\n    shown = res[\"groups\"]\n    # funnel (what the page animates): opted in -> share >= MIN_SHARED codes -> same exact set -> shown (n >= K)\n    opted = [r for r in cohort if r[\"matching_opt_in\"] and r[\"id\"] != persona[\"id\"]]\n    by_set = defaultdict(list)\n    for r in opted:\n        sh = pf & feats[r[\"id\"]]\n        if len(sh) >= MIN_SHARED:\n            by_set[sh].append(r[\"id\"])\n    share_min = sum(len(v) for v in by_set.values())\n    exact = max((len(v) for v in by_set.values()), default=0)\n    shown_ids = {i for g in shown for i in by_set[frozenset(g[\"pattern\"])]}\n    matched = [i for i, r in enumerate(cohort) if r[\"id\"] in shown_ids]\n    detail = {str(i): {k: cohort[i][k] for k in (\"country\", \"age_band\", \"labs\", \"imaging\", \"symptoms\", \"specialties\")} for i in matched}\n\n    data = {\n        \"synthetic\": True, \"label\": PAGE_LABEL, \"seed\": G.SEED, \"n\": len(cohort), \"k\": K, \"min_shared\": MIN_SHARED,\n        \"seeded\": summary[\"seeded_patterns\"],\n        \"codes\": codes, \"age_bands\": G.AGE_BANDS, \"groups\": names,\n        \"records\": rows,\n        \"persona\": {\"id\": persona[\"id\"], \"country\": persona[\"country\"], \"age_band\": persona[\"age_band\"],\n                    \"codes\": sorted(pf), \"opt_in\": persona[\"matching_opt_in\"]},\n        \"result\": {\"match_count\": res[\"match_count\"], \"groups\": shown, \"matched\": matched,\n                   \"funnel\": {\"opted_in\": len(opted), \"share_min\": share_min, \"exact\": exact, \"shown\": res[\"match_count\"]}},\n        \"detail\": detail,\n        \"vm\": None,   # filled by run_on_boxd.sh from the wrapper's real timestamps, or left null (local fallback)\n    }\n    with open(out, \"w\") as f:\n        json.dump(data, f, separators=(\",\", \":\"), sort_keys=True)\n        f.write(\"\\n\")\n    print(\"wrote %s: %d records, S=%d, shown groups %s, funnel %s\" % (\n        out, len(rows), summary[\"seeded_patterns\"].get(\"rare_sarcoid_like\", 0), [g[\"n\"] for g in shown], data[\"result\"][\"funnel\"]))\n    assert len(shown) == 1 and 5 <= shown[0][\"n\"] <= 9, \"demo patient must get exactly one group of 5 to 9\"\n\n\nif __name__ == \"__main__\":\n    if sys.argv[1:] == [\"--sweep\"]:\n        sweep()\n    else:\n        build(sys.argv[1], sys.argv[2])\n",
};
